mapper.select:
SELECT t.id AS transactionId, a.id AS accountId, i.institution_code AS institutionCode, i.institution_name AS institutionName, a.account_no_masked AS accountNoMasked, a.product_name AS productName, DATE_FORMAT(t.transacted_at, '%Y-%m-%dT%H:%i:%s+09:00') AS transactedAt, t.trans_type_code AS transTypeCode, t.trans_type_name AS transTypeName, t.amount AS amount, t.balance_after AS balanceAfter, t.description AS description, a.currency AS currency FROM bank_transaction t JOIN bank_account a ON a.id = t.bank_account_id JOIN financial_institution i ON i.id = a.institution_id WHERE a.user_id = #{userId} AND a.id = #{accountId} AND i.is_supported = 1 AND t.transacted_at <= CURRENT_TIMESTAMP
AND DATE_FORMAT(t.transacted_at, '%Y-%m') = #{yearMonth}
ORDER BY t.transacted_at DESC, t.id DESC

SELECT t.id AS transactionId, d.id AS depositAccountId, i.institution_code AS institutionCode, i.institution_name AS institutionName, d.account_no_masked AS accountNoMasked, d.product_name AS productName, d.deposit_type_code AS depositTypeCode, DATE_FORMAT(t.transacted_at, '%Y-%m-%dT%H:%i:%s+09:00') AS transactedAt, t.trans_type_code AS transTypeCode, t.trans_type_name AS transTypeName, t.amount AS amount, t.balance_after AS balanceAfter, t.description AS description, d.currency AS currency FROM deposit_transaction t JOIN deposit_account d ON d.id = t.deposit_account_id JOIN financial_institution i ON i.id = d.institution_id WHERE d.user_id = #{userId} AND d.id = #{depositAccountId} AND d.account_status_code = '01' AND i.is_supported = 1 AND t.transacted_at <= CURRENT_TIMESTAMP
AND DATE_FORMAT(t.transacted_at, '%Y-%m') = #{yearMonth}
ORDER BY t.transacted_at DESC, t.id DESC

SELECT t.id AS transactionId, l.id AS loanId, i.institution_code AS institutionCode, i.institution_name AS institutionName, l.loan_no_masked AS loanNoMasked, l.product_name AS productName, l.account_type_code AS accountTypeCode, DATE_FORMAT(t.transacted_at, '%Y-%m-%dT%H:%i:%s+09:00') AS transactedAt, t.trans_type_code AS transTypeCode, t.trans_type_name AS transTypeName, t.amount AS amount, t.principal_amount AS principalAmount, t.interest_amount AS interestAmount, t.balance_after AS balanceAfter, t.description AS description, l.currency AS currency FROM loan_transaction t JOIN loan_account l ON l.id = t.loan_account_id JOIN financial_institution i ON i.id = l.institution_id WHERE l.user_id = #{userId} AND l.id = #{loanId} AND l.account_status_code = '01' AND i.is_supported = 1 AND t.transacted_at <= CURRENT_TIMESTAMP
AND DATE_FORMAT(t.transacted_at, '%Y-%m') = #{yearMonth}
ORDER BY t.transacted_at DESC, t.id DESC

SELECT t.id AS transactionId, a.id AS securitiesAccountId, i.institution_code AS institutionCode, i.institution_name AS institutionName, a.account_no_masked AS accountNoMasked, a.product_name AS productName, a.account_type_code AS accountTypeCode, DATE_FORMAT(t.transacted_at, '%Y-%m-%dT%H:%i:%s+09:00') AS transactedAt, t.trans_type_code AS transTypeCode, t.trans_type_name AS transTypeName, t.product_code AS securityProductCode, t.product_name AS securityProductName, t.quantity AS quantity, t.unit_price AS unitPrice, t.transaction_amount AS transactionAmount, t.description AS description, a.currency AS currency FROM securities_transaction t JOIN securities_account a ON a.id = t.securities_account_id JOIN financial_institution i ON i.id = a.institution_id WHERE a.user_id = #{userId} AND a.id = #{accountId} AND a.account_status_code = '01' AND i.is_supported = 1 AND t.transacted_at <= CURRENT_TIMESTAMP
AND DATE_FORMAT(t.transacted_at, '%Y-%m') = #{yearMonth}
ORDER BY t.transacted_at DESC, t.id DESC

SELECT t.id AS transactionId, p.id AS payMoneyId, p.provider_code AS providerCode, p.provider_name AS providerName, i.institution_name AS institutionName, p.wallet_id AS walletId, p.wallet_name AS walletName, DATE_FORMAT(t.transacted_at, '%Y-%m-%dT%H:%i:%s+09:00') AS transactedAt, t.trans_type_code AS transTypeCode, t.trans_type_name AS transTypeName, t.amount AS amount, t.balance_after AS balanceAfter, t.point_amount AS pointAmount, t.point_balance_after AS pointBalanceAfter, t.merchant_name AS merchantName, t.description AS description, p.currency AS currency FROM pay_money_transaction t JOIN pay_money p ON p.id = t.pay_money_id JOIN financial_institution i ON i.id = p.institution_id WHERE p.user_id = #{userId} AND p.id = #{payMoneyId} AND i.is_supported = 1 AND t.transacted_at <= CURRENT_TIMESTAMP
AND DATE_FORMAT(t.transacted_at, '%Y-%m') = #{yearMonth}
ORDER BY t.transacted_at DESC, t.id DESC

SELECT a.id AS approvalId, c.id AS cardId, i.institution_code AS institutionCode, i.institution_name AS institutionName, c.card_no_masked AS cardNoMasked, c.product_name AS productName, c.card_product_code AS cardProductCode, a.approval_no AS approvalNo, DATE_FORMAT(a.approved_at, '%Y-%m-%dT%H:%i:%s+09:00') AS approvedAt, a.approval_type_code AS approvalTypeCode, a.approval_type_name AS approvalTypeName, a.merchant_name AS merchantName, a.merchant_business_no AS merchantBusinessNo, a.approved_amount AS approvedAmount, a.currency AS currency, a.description AS description FROM card_approval a JOIN card c ON c.id = a.card_id JOIN financial_institution i ON i.id = c.institution_id WHERE c.user_id = #{userId} AND c.id = #{cardId} AND i.is_supported = 1 AND a.approved_at <= CURRENT_TIMESTAMP
AND DATE_FORMAT(a.approved_at, '%Y-%m') = #{yearMonth}
ORDER BY a.approved_at DESC, a.id DESC

SELECT b.id AS billId, c.id AS cardId, i.institution_code AS institutionCode, i.institution_name AS institutionName, c.card_no_masked AS cardNoMasked, c.product_name AS productName, c.card_product_code AS cardProductCode, DATE_FORMAT(b.billing_month, '%Y-%m') AS billingMonth, DATE_FORMAT(b.due_date, '%Y-%m-%d') AS dueDate, b.bill_status_code AS billStatusCode, b.bill_status_name AS billStatusName, b.total_amount AS totalAmount, b.paid_amount AS paidAmount FROM card_bill b JOIN card c ON c.id = b.card_id JOIN financial_institution i ON i.id = c.institution_id WHERE c.user_id = #{userId} AND c.id = #{cardId} AND c.card_status_code = '01' AND i.is_supported = 1 AND b.billing_month <= CURRENT_DATE
AND DATE_FORMAT(b.billing_month, '%Y-%m') = #{billingMonth}
ORDER BY b.billing_month DESC, b.id DESC
